  /** declaredReceiverTypes() 的结果（每个文件建一次） */
  receiverTypes: ReadonlyMap<string, ReceiverType | null>;
  /** 本文件的 import 列表（判「接收者是不是导入名」——那种 `X.foo()` 归跨文件解析） */
  imports: ReadonlyArray<{ bindings?: string[] }>;
  callerQn: string;
  callee: string;
  calleeExpr: string;
}): CallVerdict

handleOpenAICompatRequest(body: OpenAICompatRequest): Promise<{
  status: number;
  body: unknown;
}>

prewarmKernel(): Promise<{
  warmed: number;
  /** 装了但**加载失败**的扩展名（沿用原字段名 —— 原调用方文案写「语言包」是错的，它是 ext） */
  missing: string[];
  /**
   * ★★ 2026-10-08 新增：**注册了但包没装**的语言名。
   *
   * 为什么必须报出来：它们此前落在 `warmed` 与 `missing` 的**夹缝**里，**完全看不见** ——
   * 因为原实现只遍历 `probeInstalledLanguages()`（**已装的**）⇒ 未装的**连循环都进不去**。
   * ★ `tsx` / `jsx` 就是在这里藏了很久：`.tsx` 全体解析不出来，
   *   而预热报告显示的是「34 个解析器就绪，缺 0 个语言包」—— 听起来一切正常。
   */
  notInstalled: string[];
}>

buildSyncMeta(input: {
  feature: string;
  sourceRoot?: string;
  source: string;
  /** 上一份 `_sync`：保留 `facts` 声明，并作为 `scanRev` / `dbSchemaVersion` 的**继承来源** */
  prev?: Record<string, unknown>;
  /**
   * ★ 只有"**这一次写就是在从库复制**"才传 `true`（其余一律不传）：
   * · `true` 的调用方：`saveLiveFeature`（live 视图每次都是照库现画）、`live_render`（现渲染）、
   *   `import_project` 的 fork / 重建（`saveDSL(…, {refreshScanRev:true})`）、以及**首次**（无基线）。
   * · **不传**的调用方：`saveDesignSheet`（claim/publish/release/complete 改任务）、
   *   `saveDSL` 的其它全部调用点（edit_dsl 改内容）—— 它们只前进 `saved_at`。
   */
  refreshScanRev?: boolean;
  /**
   * ★★ 2026-10-22：**这次写是谁授权的**（`edit_dsl:<…>` / `import:<…>` / `tool:<…>` / `sandbox`）。
   * ★ 2026-10-23：`canvas-patch` 这个值**已退场** —— 画布三格与批注层整体退场（详见 `docs/ROOTS.md` §8），不再走 `saveDSL`。
   * 由 `saveDSL` 从 `dsl_write_scope` 取；**不传则继承上一份** —— `saveDesignSheet` / `saveLiveFeature`
   * 这类不经过 `saveDSL` 的落盘口不该把别人的留痕冲掉。
   */
  via?: string;
}): Record<string, unknown>

registryInstallScript(pkg: string): {
  script: string | null;
  /** 上游 latest 版本号（取不到 ⇒ null） */
  version: string | null;
  /** 上游 latest 是否 NAN 绑定（取不到 ⇒ null） */
  usesNan: boolean | null;
  /**
   * 上游 latest 声明的 `peerDependencies['tree-sitter']`（没声明 ⇒ null）。
   * ★★ 2026-10-08 补：**只看"模板修了"会推荐一个装不上的版本** —— 实测 `tree-sitter-css`：
   *   latest 0.25.0 已是 node-gyp-build，但它 `peerDependencies: tree-sitter ^0.25.0`，
